--
-- Table structure for table `creature`
--

DROP TABLE IF EXISTS `creature`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `creature` (
  `id_creature` int NOT NULL AUTO_INCREMENT,
  `id_lieu` int NOT NULL,
  `type_creature` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `numero_encyclopedie` int NOT NULL,
  `nom_creature` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `prix_vente_creature` int NOT NULL,
  `ombre` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `difficulte` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meteo` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `captures_requises` int NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `phrase_capture` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `nom_fichier_creature` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id_creature`),
  UNIQUE KEY `type_creature` (`type_creature`,`nom_creature`),
  UNIQUE KEY `type_creature_2` (`type_creature`,`numero_encyclopedie`),
  KEY `id_lieu` (`id_lieu`),
  CONSTRAINT `creature_ibfk_1` FOREIGN KEY (`id_lieu`) REFERENCES `lieu` (`id_lieu`),
  CONSTRAINT `creature_chk_1` CHECK ((`type_creature` in (_utf8mb4'poisson',_utf8mb4'insecte'))),
  CONSTRAINT `creature_chk_2` CHECK ((`prix_vente_creature` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=161 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

