DROP TABLE IF EXISTS `croiser`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `croiser` (
  `id_genotype_parent_1` int NOT NULL,
  `id_genotype_parent_2` int NOT NULL,
  `id_fleur_enfant` int NOT NULL,
  `probabilite` decimal(9,8) NOT NULL,
  PRIMARY KEY (`id_genotype_parent_1`,`id_genotype_parent_2`,`id_fleur_enfant`),
  KEY `id_genotype_parent_2` (`id_genotype_parent_2`),
  KEY `id_fleur_enfant` (`id_fleur_enfant`),
  CONSTRAINT `croiser_ibfk_1` FOREIGN KEY (`id_genotype_parent_1`) REFERENCES `genotype` (`id_genotype`),
  CONSTRAINT `croiser_ibfk_2` FOREIGN KEY (`id_genotype_parent_2`) REFERENCES `genotype` (`id_genotype`),
  CONSTRAINT `croiser_ibfk_3` FOREIGN KEY (`id_fleur_enfant`) REFERENCES `fleur` (`id_fleur`),
  CONSTRAINT `croiser_chk_1` CHECK (((`probabilite` > 0) and (`probabilite` <= 1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

