DROP TABLE IF EXISTS `disponibilite`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `disponibilite` (
  `id_disponibilite` int NOT NULL AUTO_INCREMENT,
  `id_creature` int NOT NULL,
  `hemisphere` char(2) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mois` int NOT NULL,
  `heure_debut` int NOT NULL,
  `heure_fin` int NOT NULL,
  PRIMARY KEY (`id_disponibilite`),
  UNIQUE KEY `id_creature` (`id_creature`,`hemisphere`,`mois`,`heure_debut`),
  KEY `idx_dispo_moment` (`hemisphere`,`mois`),
  CONSTRAINT `disponibilite_ibfk_1` FOREIGN KEY (`id_creature`) REFERENCES `creature` (`id_creature`) ON DELETE CASCADE,
  CONSTRAINT `disponibilite_chk_1` CHECK ((`hemisphere` in (_utf8mb4'NH',_utf8mb4'SH'))),
  CONSTRAINT `disponibilite_chk_2` CHECK ((`mois` between 1 and 12)),
  CONSTRAINT `disponibilite_chk_3` CHECK ((`heure_debut` between 0 and 23)),
  CONSTRAINT `disponibilite_chk_4` CHECK ((`heure_fin` between 1 and 24))
) ENGINE=InnoDB AUTO_INCREMENT=1979 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
