DROP TABLE IF EXISTS `periode`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `periode` (
  `id_periode` int NOT NULL AUTO_INCREMENT,
  `id_evenement` int NOT NULL,
  `annee` int NOT NULL,
  `hemisphere_periode` char(2) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_debut` date NOT NULL,
  `date_fin` date NOT NULL,
  PRIMARY KEY (`id_periode`),
  UNIQUE KEY `id_evenement` (`id_evenement`,`annee`,`hemisphere_periode`),
  KEY `idx_periode_dates` (`hemisphere_periode`,`date_debut`,`date_fin`),
  CONSTRAINT `periode_ibfk_1` FOREIGN KEY (`id_evenement`) REFERENCES `evenement` (`id_evenement`) ON DELETE CASCADE,
  CONSTRAINT `periode_chk_1` CHECK ((`hemisphere_periode` in (_utf8mb4'NH',_utf8mb4'SH'))),
  CONSTRAINT `periode_chk_2` CHECK ((`date_fin` >= `date_debut`))
) ENGINE=InnoDB AUTO_INCREMENT=13843 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
