DROP TABLE IF EXISTS `villageois`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `villageois` (
  `id_villageois` int NOT NULL AUTO_INCREMENT,
  `id_espece` int NOT NULL,
  `id_personnalite` int NOT NULL,
  `id_loisir` int NOT NULL,
  `nom_villageois` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `genre` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sous_type` char(1) COLLATE utf8mb4_unicode_ci NOT NULL,
  `jour_anniversaire` int NOT NULL,
  `mois_anniversaire` int NOT NULL,
  `phrase_fetiche` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `chanson_preferee` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `citation_preferee` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `version_ajout_villageois` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nom_fichier_villageois` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id_villageois`),
  UNIQUE KEY `nom_villageois` (`nom_villageois`),
  KEY `id_espece` (`id_espece`),
  KEY `id_personnalite` (`id_personnalite`),
  KEY `id_loisir` (`id_loisir`),
  CONSTRAINT `villageois_ibfk_1` FOREIGN KEY (`id_espece`) REFERENCES `espece` (`id_espece`),
  CONSTRAINT `villageois_ibfk_2` FOREIGN KEY (`id_personnalite`) REFERENCES `personnalite` (`id_personnalite`),
  CONSTRAINT `villageois_ibfk_3` FOREIGN KEY (`id_loisir`) REFERENCES `loisir` (`id_loisir`),
  CONSTRAINT `villageois_chk_1` CHECK ((`genre` in (_utf8mb4'Male',_utf8mb4'Female'))),
  CONSTRAINT `villageois_chk_2` CHECK ((`sous_type` in (_utf8mb4'A',_utf8mb4'B'))),
  CONSTRAINT `villageois_chk_3` CHECK ((`jour_anniversaire` between 1 and 31)),
  CONSTRAINT `villageois_chk_4` CHECK ((`mois_anniversaire` between 1 and 12))
) ENGINE=InnoDB AUTO_INCREMENT=418 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

